def form_squads(candidates):
    groups = {}
    for name,role,score in candidates: groups.setdefault(role,[]).append((name,score))
    if not groups: return [[],[]]
    for values in groups.values(): values.sort(key=lambda x:(-x[1],x[0]))
    size = min(map(len,groups.values()))
    squads = [[groups[role][i][0] for role in sorted(groups)] for i in range(size)]
    left = sorted(name for values in groups.values() for name,score in values[size:])
    return [squads,left]
